function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each value of nums is an integer from 1 to 50.';
  return null;
}

