function longestMonotonicSubarray(nums) {
  let increasing = 1;
  let decreasing = 1;
  let best = 1;

  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) {
      increasing++;
      decreasing = 1;
    } else if (nums[i] < nums[i - 1]) {
      decreasing++;
      increasing = 1;
    } else {
      increasing = 1;
      decreasing = 1;
    }
    best = Math.max(best, increasing, decreasing);
  }
  return best;
}

