function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 50 : int(1, 10);
  const mode = int(0, 3);
  const nums = [];
  if (mode === 0) {
    // Values from a narrow or a full range, so equal neighbours appear sometimes.
    const top = [3, 50][int(0, 1)];
    for (let i = 0; i < n; i++) nums.push(int(1, top));
  } else if (mode === 1) {
    // Runs that keep a direction for a while, then turn or stall.
    let value = int(1, 50);
    let step = 1;
    for (let i = 0; i < n; i++) {
      nums.push(value);
      if (rand() < 0.2) step = [-1, 0, 1][int(0, 2)];
      if (value + step < 1 || value + step > 50) step = -step;
      value += step;
    }
  } else if (mode === 2) {
    // Zigzag with occasional plateaus.
    for (let i = 0; i < n; i++) nums.push(i % 2 === 0 ? int(1, 25) : int(rand() < 0.2 ? 1 : 26, 50));
  } else {
    // One long strictly monotone stretch inside random values.
    for (let i = 0; i < n; i++) nums.push(int(1, 50));
    const length = int(1, n);
    const from = int(0, n - length);
    const up = rand() < 0.5;
    const base = int(1, 51 - length);
    for (let i = 0; i < length; i++) nums[from + i] = up ? base + i : base + length - 1 - i;
  }
  return [nums];
}
